"""Generate the eight Russian lab reports from the implemented game and recorded checks."""
from pathlib import Path
import json
import sys
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'Docs/Reports'
OUT.mkdir(parents=True,exist_ok=True)
ONLY=int(sys.argv[1]) if len(sys.argv)>1 else None

def new(number,title,summary):
    d=Document();s=d.sections[0]
    s.page_width=Inches(8.5);s.page_height=Inches(11)
    s.top_margin=s.bottom_margin=Inches(.65);s.left_margin=s.right_margin=Inches(.72)
    for name in ('Normal','Title','Subtitle','Heading 1','Heading 2'):
        style=d.styles[name];style.font.name='Calibri';style.font.color.rgb=RGBColor(0,0,0)
    n=d.styles['Normal'];n.font.size=Pt(11);n.paragraph_format.space_after=Pt(6);n.paragraph_format.line_spacing=1.08
    d.styles['Title'].font.size=Pt(25);d.styles['Title'].paragraph_format.space_after=Pt(9)
    d.styles['Heading 1'].font.size=Pt(16);d.styles['Heading 1'].paragraph_format.space_before=Pt(12);d.styles['Heading 1'].paragraph_format.space_after=Pt(6)
    d.styles['Heading 2'].font.size=Pt(12);d.styles['Heading 2'].paragraph_format.space_before=Pt(8)
    d.add_paragraph(f'Лабораторная работа {number}',style='Subtitle')
    d.add_paragraph(title,style='Title')
    p(d,'Проект Neonmoves 1.3 · 29 октября 2026 · Windows x64')
    p(d,summary)
    footer=s.footer.paragraphs[0];footer.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    r=footer.add_run('Neonmoves  /  ');r.font.size=Pt(9)
    field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');footer._p.append(field)
    d.core_properties.title=f'Neonmoves Лабораторная работа {number} {title}'
    d.core_properties.subject='AI танцевальная игра на Unity'
    d.core_properties.author='Neonmoves'
    return d

def p(d,text,bold=False):
    par=d.add_paragraph();r=par.add_run(text);r.bold=bold;return par
def h(d,text):d.add_heading(text,level=1)
def page(d,title):
    if d.paragraphs and not d.paragraphs[-1].text and not d.paragraphs[-1]._p.xpath('.//w:drawing'):
        par=d.paragraphs[-1]._p
        if par.getnext() is not None and par.getnext().tag==qn('w:sectPr'):par.getparent().remove(par)
    heading=d.add_heading(title,level=1);heading.paragraph_format.page_break_before=True
def table(d,headers,rows,widths=None,size=10):
    t=d.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    if widths:
        for col,width in zip(t.columns,widths):col.width=Inches(width)
    for i,x in enumerate(headers):t.rows[0].cells[i].text=x
    for values in rows:
        for cell,x in zip(t.add_row().cells,values):cell.text=str(x)
    props=t._tbl.tblPr;borders=OxmlElement('w:tblBorders')
    for edge in ('top','left','bottom','right','insideH','insideV'):
        b=OxmlElement('w:'+edge);b.set(qn('w:val'),'single');b.set(qn('w:sz'),'4');b.set(qn('w:color'),'D9D9D9');borders.append(b)
    props.append(borders)
    repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
    for ri,row in enumerate(t.rows):
        no_split=OxmlElement('w:cantSplit');row._tr.get_or_add_trPr().append(no_split)
        for ci,cell in enumerate(row.cells):
            if widths:cell.width=Inches(widths[ci])
            cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            pr=cell._tc.get_or_add_tcPr();margins=OxmlElement('w:tcMar')
            for side in ('top','left','bottom','right'):
                mar=OxmlElement('w:'+side);mar.set(qn('w:w'),'85');mar.set(qn('w:type'),'dxa');margins.append(mar)
            pr.append(margins);sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'17324D' if ri==0 else 'F1F5F8' if ri%2==0 else 'FFFFFF');pr.append(sh)
            for par in cell.paragraphs:
                par.paragraph_format.space_after=Pt(2);par.paragraph_format.space_before=Pt(2);par.paragraph_format.line_spacing=1.02
                if ci==0 and len(headers)>2:par.alignment=WD_ALIGN_PARAGRAPH.CENTER
                for r in par.runs:r.font.size=Pt(size);r.bold=ri==0;r.font.color.rgb=RGBColor(255,255,255) if ri==0 else RGBColor(0,0,0)
    d.add_paragraph().paragraph_format.space_after=Pt(1)
    return t
def picture(d,kind,caption):
    files=sorted((ROOT/'Build/Neonmoves/Captures').glob(kind+'-*.png'))
    if files:
        d.add_picture(str(files[-1]),width=Inches(6.95))
        par=p(d,caption);par.paragraph_format.space_after=Pt(8)
        for r in par.runs:r.font.size=Pt(9)
def save(d,number):
    if ONLY is not None and number!=ONLY:return
    for root in (d.element,d.styles.element):
        for border in list(root.xpath('.//w:pBdr')):border.getparent().remove(border)
    d.save(OUT/f'Neonmoves_Lab_{number:02d}.docx')

